// This template is from P5js shader tutorial at
// https://itp-xstory.github.io/p5js-shaders/#/./docs/examples/basic_gradient
let theShader;
let balls = [];

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/1726004/files/vert.glsl', 'frag.glsl');
}

function setup() {
  // disables scaling for retina screens which can create inconsistent scaling between displays
  pixelDensity(1);
  createCanvas(windowWidth, windowHeight, WEBGL);

	for (let i = 0; i < 6; i++) {
		balls.push({
			vel: [random(), random()],
			pos: [random(width), random(height)]
		});
	}
}

function updateBalls() {
	let velX, velY;
	let posX, posY;

	let substeps = 10;
	for (let n = 0; n < substeps; n++){
		for (let i = 0; i < balls.length; i++) {
			[velX, velY] = balls[i].vel;
			[posX, posY] = balls[i].pos;
			if (posX <= 0 || posX >= width) {
				velX *= -1;
			} 
			if (posY <= 0 || posY >= height) {
				velY *= -1;
			}

			if (((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) {
				velX += ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - posX) * 0.001 * 1/substeps;
				velY += ((height - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))) - posY) * 0.001 * 1/substeps;
			} else {
				velX += cos(frameCount/100) * 0.015 * i * 1/substeps;
				velY += sin(frameCount/100) * 0.015 * i * 1/substeps;

			}

			balls[i].vel = [velX * 0.99, velY * 0.99];
			balls[i].pos = [posX + velX, posY + velY];
		}
	}
}

//function mouseReleased() {
